WITH products_by_supplier AS (SELECT supplier_id, ROUND((100 * SUM(CASE WHEN category = 'Fashion' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_fashion, ROUND(STDDEV(price), 2) AS stddev_price FROM products WHERE ARRAY_CONTAINS(tags, 'new') GROUP BY supplier_id) SELECT s.id, s.city, pbs.pct_fashion, pbs.stddev_price FROM suppliers s LEFT JOIN products_by_supplier pbs ON s.id = pbs.supplier_id ORDER BY stddev_price DESC;
